"""Make customers.email unique, ignoring ASCII case.

Customers whose emails are equal after trimming surrounding spaces and ignoring ASCII case are one person. Keep the
one with the earliest created_at (the lowest id on a tie), move every order and address of the others to it, and
delete the others. If the kept customer's name is NULL or empty, give it the name of the earliest-created duplicate
that has one. Store every customer's email trimmed, with ASCII letters lowercased; other characters stay as they are.

Afterwards the customers table declares email as `email TEXT NOT NULL COLLATE NOCASE UNIQUE`. Everything else in the
schema stays as it is: the same tables and columns, the foreign keys with ON DELETE CASCADE, the index and the view.
Every order and address survives. conn comes from store.db.connect, with foreign keys on and no open transaction;
leave foreign keys on, commit your work, and set user_version to 2.
"""

VERSION = 2

# Same text as schema.sql, except for the email line.
NEW_CUSTOMERS = """CREATE TABLE customers (
    id INTEGER PRIMARY KEY,
    email TEXT NOT NULL COLLATE NOCASE UNIQUE,
    name TEXT,
    created_at TEXT NOT NULL
)"""

# Only ASCII letters are folded, which is exactly what COLLATE NOCASE ignores.
_ASCII_LOWER = {c: c + 32 for c in range(ord("A"), ord("Z") + 1)}


def _normalize(email):
    if not isinstance(email, str):
        return email
    return email.strip(" ").translate(_ASCII_LOWER)


def _age_key(row):
    """Sort key: earliest created_at first, lowest id on a tie."""
    cid, created_at, instant = row[0], row[3], row[4]
    if instant is not None:
        return (0, instant, "", cid)
    return (1, 0.0, str(created_at), cid)


def _quote(name):
    return '"' + name.replace('"', '""') + '"'


def _referencing_columns(conn):
    """(table, column) pairs holding a foreign key to customers.id."""
    found = []
    tables = [r[0] for r in conn.execute("SELECT name FROM sqlite_master WHERE type = 'table'")]
    for table in tables:
        for fk in conn.execute("PRAGMA foreign_key_list(%s)" % _quote(table)).fetchall():
            if fk[2].lower() == "customers" and (fk[4] is None or fk[4].lower() == "id"):
                found.append((table, fk[3]))
    return found


def upgrade(conn):
    if conn.execute("PRAGMA user_version").fetchone()[0] >= VERSION:
        return

    # Replacing the customers table means dropping it, and with foreign keys on that would cascade into orders and
    # addresses. The pragma only takes effect outside a transaction, so make sure it really went off.
    conn.execute("PRAGMA foreign_keys = OFF")
    try:
        if conn.execute("PRAGMA foreign_keys").fetchone()[0]:
            raise RuntimeError("m0002 needs a connection with no open transaction")
        conn.execute("BEGIN IMMEDIATE")
        try:
            _migrate(conn)
            conn.execute("PRAGMA user_version = %d" % VERSION)
            conn.commit()
        except BaseException:
            conn.rollback()
            raise
    finally:
        conn.execute("PRAGMA foreign_keys = ON")


def _migrate(conn):
    broken_before = set(conn.execute("PRAGMA foreign_key_check").fetchall())

    rows = conn.execute(
        "SELECT id, email, name, created_at,"
        " CASE WHEN typeof(created_at) = 'text' THEN julianday(created_at) END"
        " FROM customers"
    ).fetchall()

    groups = {}
    for row in rows:
        email = _normalize(row[1])
        groups.setdefault((type(email).__name__, email), []).append(row)

    kept = []  # (id, email, name, created_at)
    moves = []  # (kept id, duplicate id)
    for (_, email), members in groups.items():
        members.sort(key=_age_key)
        keeper = members[0]
        name = keeper[2]
        if name is None or name == "":
            for other in members[1:]:
                if other[2] is not None and other[2] != "":
                    name = other[2]
                    break
        kept.append((keeper[0], email, name, keeper[3]))
        moves.extend((keeper[0], other[0]) for other in members[1:])
    kept.sort(key=lambda r: r[0])

    if moves:
        for table, column in _referencing_columns(conn):
            conn.executemany(
                "UPDATE %s SET %s = ? WHERE %s = ?" % (_quote(table), _quote(column), _quote(column)), moves
            )

    # Explicit indexes and triggers on customers go away with the table; put them back afterwards.
    extras = [
        r[0]
        for r in conn.execute(
            "SELECT sql FROM sqlite_master"
            " WHERE tbl_name = 'customers' COLLATE NOCASE AND type IN ('index', 'trigger') AND sql IS NOT NULL"
        )
    ]

    # Recreating the table under its own name (no rename) leaves the references in orders, addresses and the view
    # untouched.
    conn.execute("DROP TABLE customers")
    conn.execute(NEW_CUSTOMERS)
    conn.executemany("INSERT INTO customers (id, email, name, created_at) VALUES (?, ?, ?, ?)", kept)
    for sql in extras:
        conn.execute(sql)

    broken_after = set(conn.execute("PRAGMA foreign_key_check").fetchall())
    if broken_after - broken_before:
        raise RuntimeError("m0002 would break foreign keys: %r" % sorted(broken_after - broken_before, key=repr))

