"""A Store with ledger.store.Store's interface that really is shared between OS processes (test only).

Values are one file per key under a directory; get/put/compare_and_put are made atomic with a
flock on a mutex file; lock(key) is a flock on a per-key lock file, opened afresh on every call so
it is not reentrant, like the real store's.
"""
import contextlib
import fcntl
import hashlib
import os


class FileStore:
    def __init__(self, root):
        self.root = root
        os.makedirs(os.path.join(root, "data"), exist_ok=True)
        os.makedirs(os.path.join(root, "locks"), exist_ok=True)

    def _path(self, kind, key):
        return os.path.join(self.root, kind, hashlib.sha1(repr(key).encode()).hexdigest())

    @contextlib.contextmanager
    def _flock(self, path):
        fd = os.open(path, os.O_CREAT | os.O_RDWR, 0o600)
        try:
            fcntl.flock(fd, fcntl.LOCK_EX)
            yield
        finally:
            os.close(fd)  # closing drops the flock

    def _mutex(self):
        return self._flock(os.path.join(self.root, "mutex"))

    def _read(self, key):
        try:
            with open(self._path("data", key)) as f:
                return int(f.read())
        except FileNotFoundError:
            return None

    def _write(self, key, value):
        with open(self._path("data", key), "w") as f:
            f.write(str(value))

    def get(self, key):
        with self._mutex():
            return self._read(key)

    def put(self, key, value):
        with self._mutex():
            self._write(key, value)

    def compare_and_put(self, key, expected, value):
        with self._mutex():
            if self._read(key) != expected:
                return False
            self._write(key, value)
            return True

    def lock(self, key):
        return self._flock(self._path("locks", key))

